@push('scripts')
<script>
(() => {
const form=document.getElementById('productForm'),input=document.getElementById('fileInput'),modal=document.getElementById('uploadModal'),modalFiles=document.getElementById('modalFiles'),uploadedList=document.getElementById('uploadedList'),dropzone=document.getElementById('dropzone'),modalDrop=document.getElementById('modalDrop');let selected=[],uploaded=[],draftId=@json($draft?->id),timer;
const key='digitalshop_product_draft_v2',size=n=>n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';
const payload=()=>({title:form.title.value,category_id:form.category_id.value,slug:form.slug.value,price:form.price.value,storage_provider_id:form.storage_provider_id.value,short_description:form.short_description.value,description:form.description.value,upload_ids:uploaded.map(x=>x.id)});
function save(){clearTimeout(timer);const p=payload();localStorage.setItem(key,JSON.stringify(p));document.getElementById('autosaveStatus').textContent='در حال ذخیره...';timer=setTimeout(async()=>{try{const r=await fetch(@json(route('admin.products.draft.store')),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token()),Accept:'application/json'},body:JSON.stringify({draft_id:draftId,payload:p})});const d=await r.json();if(d.ok){draftId=d.draft_id;document.getElementById('autosaveStatus').textContent='ذخیره شد · '+new Date(d.saved_at).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}}catch(e){document.getElementById('autosaveStatus').textContent='ذخیره محلی انجام شد'}}},1600)}
function apply(p){if(!p)return;['title','category_id','slug','price','storage_provider_id','short_description','description'].forEach(k=>{if(form[k]&&p[k]!=null)form[k].value=p[k]});counts()}
try{const p=JSON.parse(localStorage.getItem(key)||'null');if(p)apply(p)}catch(e){}
form.querySelectorAll('input,select,textarea').forEach(x=>x.addEventListener('input',save));form.querySelectorAll('select').forEach(x=>x.addEventListener('change',save));
fetch(@json(route('admin.products.draft.show')),{headers:{Accept:'application/json'}}).then(r=>r.json()).then(d=>{if(d.ok&&d.draft){draftId=d.draft.id;const local=localStorage.getItem(key);if(!local)apply(d.draft.payload)}}).catch(()=>{});
function open(){modal.hidden=false;document.body.style.overflow='hidden'}function close(){modal.hidden=true;document.body.style.overflow='';selected=[];renderSelected()}document.getElementById('openUploader').onclick=open;document.querySelectorAll('[data-close-upload]').forEach(x=>x.onclick=close);document.getElementById('modalChoose').onclick=()=>input.click();input.onchange=()=>{add(input.files);input.value=''};
function valid(f){return ['pdf','doc','docx'].includes(f.name.split('.').pop().toLowerCase())&&f.size<=200*1024*1024}function add(fs){const a=Array.from(fs);if(a.some(f=>!valid(f)))alert('فقط PDF، DOC و DOCX تا سقف 200MB مجاز هستند.');selected=selected.concat(a.filter(valid));renderSelected()}
['dragenter','dragover'].forEach(e=>{dropzone.addEventListener(e,x=>{x.preventDefault();dropzone.classList.add('drag')});modalDrop.addEventListener(e,x=>{x.preventDefault();modalDrop.classList.add('drag')})});['dragleave','drop'].forEach(e=>{dropzone.addEventListener(e,x=>{x.preventDefault();dropzone.classList.remove('drag')});modalDrop.addEventListener(e,x=>{x.preventDefault();modalDrop.classList.remove('drag')})});dropzone.ondrop=e=>{open();add(e.dataTransfer.files)};modalDrop.ondrop=e=>add(e.dataTransfer.files);
function renderSelected(){modalFiles.innerHTML='';selected.forEach((f,i)=>{const r=document.createElement('div');r.className='modal-file';r.innerHTML='<div class="modal-file-head"><b></b><button type="button" class="remove-file">حذف</button></div><small>'+size(f.size)+'</small><div class="progress"><i></i></div>';r.querySelector('b').textContent=f.name;r.querySelector('button').onclick=()=>{selected.splice(i,1);renderSelected()};modalFiles.appendChild(r)})}
document.getElementById('uploadSelected').onclick=async()=>{if(!selected.length)return;if(!form.storage_provider_id.value){alert('ابتدا محل نگهداری فایل را انتخاب کنید.');return}const fs=selected.slice();for(let i=0;i<fs.length;i++)await upload(fs[i],i);selected=[];renderSelected();save()};
function upload(file,i){return new Promise(done=>{const xhr=new XMLHttpRequest();xhr.open('POST',@json(route('admin.products.uploads.store')));xhr.setRequestHeader('X-CSRF-TOKEN',@json(csrf_token()));xhr.setRequestHeader('Accept','application/json');const bar=modalFiles.children[i]?.querySelector('i');xhr.upload.onprogress=e=>{if(e.lengthComputable&&bar)bar.style.width=(e.loaded/e.total*100)+'%'};xhr.onload=()=>{try{const d=JSON.parse(xhr.responseText);if(xhr.status>=200&&xhr.status<300&&d.ok){uploaded.push(d.file);renderUploaded()}else alert(d.message||'آپلود ناموفق بود.')}catch(e){alert('پاسخ نامعتبر از سرور.')}done()};xhr.onerror=()=>{alert('ارتباط با سرور قطع شد.');done()};const fd=new FormData();fd.append('file',file);fd.append('storage_provider_id',form.storage_provider_id.value);xhr.send(fd)})}
function renderUploaded(){uploadedList.innerHTML='';uploaded.forEach(f=>{const r=document.createElement('div');r.className='uploaded-item';r.innerHTML='<div><div class="uploaded-name"></div><div class="uploaded-meta"></div></div><button type="button" class="remove-file">حذف</button>';r.querySelector('.uploaded-name').textContent=f.name;r.querySelector('.uploaded-meta').textContent=f.extension+' · '+size(f.size)+' · آماده';r.querySelector('button').onclick=async()=>{const url=@json(route('admin.products.uploads.destroy',['upload'=>'UPLOAD_ID'])).replace('UPLOAD_ID',f.id);const res=await fetch(url,{method:'DELETE',headers:{'X-CSRF-TOKEN':@json(csrf_token()),Accept:'application/json'}});if(res.ok){uploaded=uploaded.filter(x=>x.id!==f.id);renderUploaded();save()}};uploadedList.appendChild(r)});form.querySelectorAll('input[name="upload_ids[]"]').forEach(x=>x.remove());uploaded.forEach(f=>{const h=document.createElement('input');h.type='hidden';h.name='upload_ids[]';h.value=f.id;form.appendChild(h)})}
function counts(){document.getElementById('shortCount').textContent=document.getElementById('short_description').value.length.toLocaleString('fa-IR')+' / ۱۰۰۰';const t=document.getElementById('description').value.trim();document.getElementById('wordCount').textContent=(t?t.split(/\s+/).length:0).toLocaleString('fa-IR')+' کلمه'}counts();document.getElementById('short_description').oninput=counts;document.getElementById('description').oninput=()=>{counts();save()};
document.querySelectorAll('.editor-toolbar [data-cmd]').forEach(b=>b.onclick=()=>{document.getElementById('description').focus();document.execCommand(b.dataset.cmd,false,b.dataset.value||null);save()});document.getElementById('previewDescription').onclick=()=>{const w=window.open('','_blank');w.document.write('<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><style>body{font-family:Tahoma;line-height:2;max-width:850px;margin:40px auto;padding:20px}h1{display:none}</style><body><h1>پیش‌نمایش</h1><div>'+document.getElementById('description').value.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])).replace(/\n/g,'<br>')+'</div></body>');w.document.close()};
form.onsubmit=e=>{if(!uploaded.length){e.preventDefault();alert('حداقل یک فایل محصول باید آپلود شود.');open();return}localStorage.removeItem(key)};
})();
</script>
@endpush
